foreach ( $stems as $s ) {
	$base = basename( $s );
	$l = '%' . $wpdb->esc_like( $base ) . '%';
	$n = array(
		'post' => (int) $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM {$wpdb->posts} WHERE post_status='publish' AND post_type NOT IN ('revision','attachment') AND post_content LIKE %s", $l ) ),
		'meta' => (int) $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM {$wpdb->postmeta} m JOIN {$wpdb->posts} p ON p.ID=m.post_id WHERE p.post_status='publish' AND p.post_type NOT IN ('revision','attachment') AND m.meta_value LIKE %s", $l ) ),
