		'opt'  => (int) $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM {$wpdb->options} WHERE option_name NOT LIKE 'opimg%%' AND option_name NOT LIKE '%%backup%%' AND option_name NOT LIKE '%%smush%%' AND option_name NOT LIKE '\\_%%transient%%' AND option_value LIKE %s", $l ) ),
	);
	$aid = (int) $wpdb->get_var( $wpdb->prepare( "SELECT post_id FROM {$wpdb->postmeta} WHERE meta_key='_wp_attached_file' AND meta_value LIKE %s LIMIT 1", '%' . $wpdb->esc_like( $base ) . '.%' ) );
	if ( $aid ) {
		$n['thumb'] = (int) $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM {$wpdb->postmeta} m JOIN {$wpdb->posts} p ON p.ID=m.post_id WHERE p.post_status='publish' AND m.meta_key='_thumbnail_id' AND m.meta_value=%s", (string) $aid ) );
		$n['gal'] = (int) $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM {$wpdb->postmeta} m JOIN {$wpdb->posts} p ON p.ID=m.post_id WHERE p.post_status='publish' AND m.meta_key='_product_image_gallery' AND CONCAT(',', m.meta_value, ',') LIKE %s", '%,' . $aid . ',%' ) );
	}
	$n = array_filter( $n );
	if ( $n ) {
		$out[] = $base . ' ' . http_build_query( $n, '', ',' );
	}
}
